namespace Joli\JoliNotif\tests\Driver;

use Joli\JoliNotif\Driver\DriverInterface;
use Joli\JoliNotif\Driver\PowerShellDriver;
use Joli\JoliNotif\Notification;
use Psr\Log\NullLogger;

class PowerShellDriverTest extends AbstractDriverTestCase
{
    use AbstractCliBasedDriverTestTrait;

    private const BINARY = 'powershell.exe';

    public function testGetBinary(): void
    {
        $driver = $this->getDriver();

        $this->assertStringContainsString('powershell', $driver->getBinary());
    }

    public function testGetPriority(): void
    {
        $driver = $this->getDriver();

        $this->assertSame(DriverInterface::PRIORITY_HIGH, $driver->getPriority());
    }

    public function testItDoesNotEvaluatePowerShellExpressions(): void
    {
        $notification = (new Notification())
            ->setBody($body = 'it\'s $(whoami) `"; whoami; `" ’); whoami; (‘')
        ;

        $arguments = $this->getCommandLineArguments($this->getDriver(), $notification);
        $script = iconv('UTF-16LE', 'UTF-8', (string) base64_decode((string) $arguments[3], true));

        $this->assertIsString($script);
        $this->assertStringNotContainsString('whoami', $script);
        $this->assertStringContainsString("FromBase64String('" . base64_encode($body) . "')", $script);
    }

    protected function getDriver(): PowerShellDriver
    {
        return new PowerShellDriver(new NullLogger());
    }

    protected static function getExpectedCommandLineForNotification(): string
    {
        return <<<'CLI'
            'powershell.exe' '-NoProfile' '-NonInteractive' '-EncodedCommand' ''
            CLI;
    }

    protected static function getExpectedCommandLineForNotificationWithATitle(): string
    {
        return <<<'CLI'
            'powershell.exe' '-NoProfile' '-NonInteractive' '-EncodedCommand' ''
            CLI;
    }

    protected static function getExpectedCommandLineForNotificationWithASubtitle(): string
    {
        return <<<'CLI'
            'powershell.exe' '-NoProfile' '-NonInteractive' '-EncodedCommand' ''
            CLI;
    }

    protected static function getExpectedCommandLineForNotificationWithASound(): string
    {
        return <<<'CLI'
            'powershell.exe' '-NoProfile' '-NonInteractive' '-EncodedCommand' ''
            CLI;
    }

    protected static function getExpectedCommandLineForNotificationWithAnIcon(): string
    {
        return self::withActualIconDir(<<<'CLI'
            'powershell.exe' '-NoProfile' '-NonInteractive' '-EncodedCommand' ''
            CLI);
    }

    protected static function getExpectedCommandLineForNotificationWithAllOptions(): string
    {
        return self::withActualIconDir(<<<'CLI'
            'powershell.exe' '-NoProfile' '-NonInteractive' '-EncodedCommand' ''
            CLI);
    }

    /**
     * Fixtures are generated with the icon located in /tmp so the encoded
     * command can be copied and run as-is. Swap the path when the temp
     * directory is elsewhere (e.g. on macOS).
     */
    private static function withActualIconDir(string $commandLine): string
    {
        $iconDir = self::getIconDir();

        if ('/tmp/jolinotif-tests-fixtures' === $iconDir) {
            return $commandLine;
        }

        return preg_replace_callback('/\'([A-Za-z0-9+\/=]+)\'$/', static function (array $matches) use ($iconDir): string {
            $script = (string) iconv('UTF-16LE', 'UTF-8', (string) base64_decode($matches[1], true));
            $script = str_replace(
                base64_encode('file:////tmp/jolinotif-tests-fixtures/image.gif'),
                base64_encode('file:///' . $iconDir . '/image.gif'),
                $script,
            );

            return "'" . base64_encode((string) iconv('UTF-8', 'UTF-16LE', $script)) . "'";
        }, $commandLine) ?? $commandLine;
    }
}
